	const item = { sourceDeclaration: "Proofs.keep"
		, erasedProofs: [
			{ sourceIndex: 0, name: "first", proposition: "True", witness: "True.intro" }
			, { sourceIndex: 2, name: "second", proposition: "True", witness: "True.intro" }
