test("compiler metadata erases an exact closed True proof parameter without changing runtime arity", async () => {
	const { request, report } = sample();
	const declaration = report.modules[0].declarations[0];
	declaration.typeExpression = "(value : UInt32) → (_proof : True) → UInt32";
	declaration.parameters.push({ name: "_proof", binderInfo: "explicit", typeExpression: "True" });
	declaration.projection.erasedProofs = [{ sourceIndex: 1, name: "_proof"
		, proposition: "True", witness: "True.intro" }];
	assert.equal(validateElaboratedMetadata(report, request), true);
	await assertJsonSchema("elaborated-export-metadata", report);
	const project = { name: "sample", version: "1.0.0", toolchain: request.metadata.toolchain };
	const analysis = projectElaboratedMetadata({ project, inputs: [], sourceTreeSha256: "e".repeat(64) }
		, [{ module: "Sample", path: "Sample.lean" }], { request, metadata: report });
	const runtime = analysis.bindingIr.document.declarations[0];
	assert.equal(runtime.parameters.length, 1);
	assert.deepEqual(runtime.source.extensions["lean-lang.org/erased-proofs"], {
		parameters: declaration.projection.erasedProofs
	});
	for(const change of [
		value => { value.sourceIndex = 0; }
		, value => { value.sourceIndex = 2; }
		, value => { value.name = "other"; }
		, value => { value.proposition = "False"; }
		, value => { value.witness = "fabricated"; }
	]) {
		const invalid = structuredClone(report);
		change(invalid.modules[0].declarations[0].projection.erasedProofs[0]);
		assert.throws(() => validateElaboratedMetadata(invalid, request)
			, { code: "invalid-elaborated-metadata" });
	}
});

test("fresh Lean erases a closed proof binder and refuses conditional or proof-result APIs", { skip: !enabled }, async t => {
	const context = await lakeWorkspaceFixture(t);
	await saveLakeFile(context.root, "Shop.lean", `namespace Shop
def keep (value : UInt32) (_proof : True) : UInt32 := value
theorem keep_eq (value : UInt32) (proof : True) : keep value proof = value := rfl
def conditional (value : UInt32) (_proof : value = 0) : UInt32 := value
def proofValue : True := True.intro
end Shop
`);
	await saveLakeFile(context.root, "lean-bridge.exports.json", canonicalJson({
		schemaVersion: 1, modules: ["Shop"]
		, exports: ["Shop.keep", "Shop.conditional", "Shop.proofValue"]
	}));
	const report = await inspect(context);
	const declarations = report.elaboration.metadata.modules[0].declarations;
	const keep = declarations.find(item => item.identity === "Shop.keep");
	assert.equal(keep.projection.status, "supported");
	assert.equal(keep.projection.parameters.length, 1);
	assert.deepEqual(keep.projection.erasedProofs, [{ sourceIndex: 1
		, name: "_proof"
		, proposition: "True", witness: "True.intro" }]);
	assert.deepEqual(keep.theoremReferences, ["Shop.keep_eq"]);
	const runtime = report.bindingIr.document.declarations.find(item => item.id === "lean:Shop.keep");
	assert.equal(runtime.parameters.length, 1);
	assert.deepEqual(runtime.source.extensions["lean-lang.org/erased-proofs"], {
		parameters: keep.projection.erasedProofs
	});
	assert.deepEqual(report.elaboration.metadata.diagnostics.map(item => item.code).sort()
		, ["proof-only", "unsupported-proof-obligation"]);
	assert.equal(declarations.find(item => item.identity === "Shop.conditional").projection.reason
		, "unsupported-proof-obligation");
	assert.equal(declarations.find(item => item.identity === "Shop.proofValue").projection.reason
		, "proof-only");
	await assertJsonSchema("elaborated-export-metadata", report.elaboration.metadata);
});

test("an independently reviewed closed proof binder preserves one runtime slot and exact compiler evidence", () => {
	const fixture = nativeMetadataFixture();
	const declaration = fixture.metadata.modules[0].declarations[0];
	declaration.typeExpression = "(value : UInt32) → (_proof : True) → UInt32";
	declaration.parameters.push({ name: "_proof", binderInfo: "explicit"
		, typeExpression: "True" });
	declaration.projection.erasedProofs = [{ sourceIndex: 1, name: "_proof"
		, proposition: "True", witness: "True.intro" }];
	const model = createNativeModel({ ...fixture
		, component: { id: "sample@1.0.0", name: "sample", version: "1.0.0" } });
	assert.equal(model.exports[0].parameters.length, 1);
	assert.deepEqual(model.exports[0].erasedProofs
		, declaration.projection.erasedProofs);
	const generated = generateNativeLeanAdapters(model);
	assert.match(generated.leanSource
		, /_root_\.Sample\.increment a0 _root_\.True\.intro/u);
	assert.match(generated.header
		, new RegExp(`uint32_t ${model.exports[0].symbol}\\(uint32_t a0\\);`, "u"));
	assert.doesNotMatch(generated.header, /proof/iu);
	const refinedModel = structuredClone(model);
	refinedModel.exports[0].refinements = { parameters: [null], result: null };
	assert.match(generateNativeLeanAdapters(refinedModel).leanSource
		, /_root_\.Sample\.increment a0 _root_\.True\.intro/u);

	const compiled = model.bindingIr;
	const reviewed = structuredClone(compiled);
	for(const producer of reviewed.producers) producer.extensions = {};
	for(const item of reviewed.declarations)
		item.source.extensions = { [erasedProofsKey]: structuredClone(
			item.source.extensions[erasedProofsKey]) };
	const review = reviewInput(reviewed);
	validateReviewedSource(review);
	const configuration = { schemaVersion: 1, modules: ["Sample"] };
	const exportConfigurationSource = canonicalJson(configuration);
	const identity = { ...fixture.sourceIdentity, exportConfigurationSource
		, exportConfigurationSha256: sha256(exportConfigurationSource) };
	assert.deepEqual(reconcileReviewedSource(review, compiled, identity), compiled);

	for(const mutate of [
		proof => { proof.sourceIndex = 0; }
		, proof => { proof.name = "other"; }
		, proof => { proof.proposition = "False"; }
	]) {
		const changed = structuredClone(reviewed);
		mutate(changed.declarations[0].source.extensions[erasedProofsKey].parameters[0]);
		assert.throws(() => reconcileReviewedSource(reviewInput(changed), compiled, identity)
			, { code: "reviewed-ir-source-mismatch" });
	}
	const changedSource = structuredClone(compiled);
	changedSource.declarations[0].source.declaration = "Sample.other";
	assert.throws(() => reconcileReviewedSource(review, changedSource, identity)
		, { code: "reviewed-ir-source-mismatch" });
	const forgedTheorem = structuredClone(reviewed);
	forgedTheorem.declarations[0].source.extensions["lean-lang.org/theorem-references"]
		= ["Sample.fabricated"];
	assert.throws(() => validateReviewedSource(reviewInput(forgedTheorem))
		, { code: "reviewed-ir-build-unsupported" });
});

test("owned review preserves exact direct proof erasure without adding a payload field", () => {
	const { document, compiled, sourceIdentity } = fixture();
	const declaration = document.declarations[0];
	const proof = { sourceIndex: declaration.parameters.length, name: "_proof"
		, proposition: "True", witness: "True.intro" };
	declaration.source.extensions["lean-lang.org/erased-proofs"]
		= { parameters: [proof] };
	compiled.declarations[0].source.extensions["lean-lang.org/erased-proofs"]
		= { parameters: [structuredClone(proof)] };
	const review = capture(document);
	sourceIdentity.reviewedBindingIr = review;
	assert.deepEqual(reconcileReviewedOwnedSource(review, compiled, sourceIdentity)
		.declarations[0].parameters, compiled.declarations[0].parameters);
	const changed = structuredClone(document);
	changed.declarations[0].source.extensions["lean-lang.org/erased-proofs"]
		.parameters[0].proposition = "False";
	assert.throws(() => reconcileReviewedOwnedSource(
		capture(changed), compiled, { ...sourceIdentity, reviewedBindingIr: capture(changed) }
	), { code: "reviewed-ir-source-mismatch" });
});
